import{_ as e,o as t,c as o,a5 as n}from"./chunks/framework.DJo0M80U.js";const _=JSON.parse('{"title":"mac 安装Maven","description":"","frontmatter":{"title":"mac 安装Maven","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","构建运维","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第七部分：构建与运维/01-Maven/mac 安装Maven.md","filePath":"posts/java快速入门/第七部分：构建与运维/01-Maven/mac 安装Maven.md"}'),r={name:"posts/java快速入门/第七部分：构建与运维/01-Maven/mac 安装Maven.md"};function p(s,a,i,l,c,v){return t(),o("div",null,[...a[0]||(a[0]=[n('<div><p>要注意版本的选择，要与jdk和springboot版本兼容； Maven 安装及配置大体可以划分为三个步骤：下载、安装和配置。 1.下载 打开 Maven 官方下载页面：[<a href="https://links.jianshu.com/go?to=https%3A%2F%2Fmaven.apache.org%2Fdownload.cgi%23" target="_blank" rel="noreferrer">https://maven.apache.org/download.cgi#</a>，点击下载链接即可开始下载：]</p><p>clipboard_20211201_041716.png 以 Maven 3.8.4 为例，解压后可以看到文件夹：apache-maven-3.8.4。 进行下一步之前，需要按照官方说明确认 JDK 已安装完成：</p><p>clipboard_20211201_041816.png 打开命令行终端，输入命令：<code>java -version</code></p><p>clipboard_20211201_041922.png 如果可以看到类似输出（可能 JDK 版本不一样），表示 JDK 已安装完成，且工作正常。 2.安装 将文件夹 apache-maven-3.8.4 拷贝或移动至系统目录 /usr/local（也可以根据个人喜好选择其它目录），Maven 安装完成。 注：涉及系统目录或系统文件的操作，可以需要 sudo 权限，下同。 3.配置 Maven 配置文件：/usr/local/apache-maven-3.8.4/conf/settings.xml。 本地仓库目录 Maven 本地仓库用于缓存已下载（远程）的 Jar 及相关文件，默认目录为用户主目录（~/.m2/repository），如果是win系统会占用C盘空间。建议统一配置为其它目录：</p><p>vim settings.xml￼// ==建议在==<code>maven</code>==目录下==<code>bin</code>==同级创建==<code>mvn_resp</code>==目录用来存放==</p><p>￼&lt;localRepository&gt;/usr/local/apache-maven-3.8.4/mvn_resp&lt;/localRepository&gt; 阿里云仓库镜像 添加阿里云仓库镜像，加速文件下载（远程）速度。</p><p>vim settings.xml￼ &lt;mirror&gt;&lt;id&gt;aliyunmaven&lt;/id&gt;&lt;mirrorOf&gt;*&lt;/mirrorOf&gt;&lt;name&gt;aliyun&lt;/name&gt;&lt;url&gt;<a href="https://maven.aliyun.com/repository/public%5C" target="_blank" rel="noreferrer">https://maven.aliyun.com/repository/public\\</a>&lt;/url&gt;&lt;/mirror&gt; 系统环境变量 打开命令行终端，输入命令：mvn -version，会提示找不到命令; 需要将 mvn 添加到系统环境变量里：</p><p>vim ~/.bash_profile ￼ export M2_HOME=/usr/local/apache-maven-3.8.4 ￼export PATH=$PATH:$M2_HOME/bin ￼ vim命令： MAC 终端编辑完成后如何保存 如果是vi，则：输入i表示开始输入，Esc 退出编辑模式，输入以下命令： :wq 保存后退出vi，若为:wq!则为强制储存后退出（常用） :w 保存但不退出（常用） :w! 若文件属性为『只读』时，强制写入该档案 :q 离开 vi （常用） :q! 若曾修改过档案，又不想储存，使用!为强制离开不储存档案。 :e! 将档案还原到最原始的状态！ 注：Mac 系统环境变量配置文件支持多个，这里仅以 ~/.bash_profile 为例。 添加完成之后，可以手动执行命令：</p><p><code>source ~/.bash_profile ￼</code> 强制系统环境变量生效；或者也可以关闭/重新打开命令行终端，系统环境变量会自动生效。再次输入命令：mvn -version 如果可以看到类似输出（可能 Maven 或 JDK 版本不一样），表示 Maven 已安装完成，且工作正常。</p></div>',1)])])}const d=e(r,[["render",p]]);export{_ as __pageData,d as default};
